    ["UI_SC_Doctrine_CloseDefense_Tooltip"] = "\\u0623\\u0632\\u0644 \\u0627\\u0644\\u062A\\u0647\\u062F\\u064A\\u062F\\u0627\\u062A \\u0627\\u0644\\u0642\\u0631\\u064A\\u0628\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0641\\u0631\\u064A\\u0642 \\u0628\\u062F\\u0648\\u0646 \\u0645\\u0627 \\u062A\\u0644\\u0627\\u062D\\u0642 \\u0632\\u0648\\u0645\\u0628\\u064A \\u0628\\u0639\\u064A\\u062F. \\u0627\\u0633\\u062A\\u0639\\u0645\\u0644 \\u0623\\u0641\\u0636\\u0644 \\u0633\\u0644\\u0627\\u062D \\u0645\\u062A\\u0627\\u062D. \\u0645\\u0627 \\u062A\\u0637\\u0644\\u0642 \\u0646\\u0627\\u0631 \\u0645\\u0646 \\u0645\\u0631\\u0643\\u0628\\u0629.",
