    ["UI_SC_Base_ProductionNeedsStorage"] = "\\u0633\\u062C\\u0651\\u0644 \\u062D\\u0627\\u0648\\u064A\\u0629 \\u0645\\u062E\\u064A\\u0645 \\u0645\\u062D\\u0645\\u0651\\u0644\\u0629 \\u0641\\u064A\\u0647\\u0627 \\u0627\\u0644\\u0633\\u062D\\u0628 \\u0623\\u0648 \\u0627\\u0644\\u0625\\u064A\\u062F\\u0627\\u0639 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0639\\u064A\\u0651\\u0646 \\u0647\\u0627\\u0644\\u0634\\u063A\\u0644\\u0629.",
    ["UI_SC_Base_ProductionNeedsWorker"] = "\\u0627\\u062E\\u062A\\u0627\\u0631 \\u0631\\u0641\\u064A\\u0642 \\u0645\\u062C\\u0646\\u0651\\u062F \\u0644\\u062A\\u0639\\u064A\\u0651\\u0646 \\u0627\\u0644\\u0625\\u0646\\u062A\\u0627\\u062C.",
    ["UI_SC_Base_ProductionHint_fell_trees"] = "\\u0628\\u064A\\u0642\\u0637\\u0639 \\u0623\\u0634\\u062C\\u0627\\u0631 \\u0648\\u0627\\u0642\\u0641\\u0629 \\u0628\\u0645\\u0646\\u0637\\u0642\\u0629 \\u062D\\u0637\\u0628 \\u0628\\u062A\\u0646\\u062E\\u062A\\u0627\\u0631 \\u062A\\u0644\\u0642\\u0627\\u0626\\u064A\\u0627\\u064B \\u0628\\u0641\\u0623\\u0633 \\u0645\\u0646 \\u0645\\u062E\\u0632\\u0646 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645. \\u0627\\u0644\\u0645\\u0646\\u0637\\u0642\\u0629 \\u0627\\u0644\\u0644\\u064A \\u0641\\u064A\\u0647\\u0627 \\u0623\\u0643\\u062A\\u0631 \\u0623\\u0634\\u062C\\u0627\\u0631 \\u0648\\u0627\\u0642\\u0641\\u0629 \\u063A\\u064A\\u0631 \\u0645\\u062D\\u062C\\u0648\\u0632\\u0629 \\u0628\\u062A\\u0646\\u062E\\u062A\\u0627\\u0631 \\u0628\\u0634\\u0643\\u0644 \\u062B\\u0627\\u0628\\u062A. \\u0645\\u0645\\u0643\\u0646 \\u062A\\u0628\\u0639\\u062F \\u0645\\u0646\\u0637\\u0642\\u0629 \\u0627\\u0644\\u062D\\u0637\\u0628 \\u0644\\u062D\\u062F 30 \\u0645\\u0631\\u0628\\u0639 \\u0628\\u0631\\u0651\\u0627 \\u062D\\u062F\\u0648\\u062F \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645\\u061B \\u0648\\u0628\\u0631\\u0651\\u0627 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0645\\u0627 \\u0628\\u064A\\u0628\\u062F\\u0623 \\u0634\\u062C\\u0631\\u0629 \\u062C\\u062F\\u064A\\u062F\\u0629 \\u0628\\u0627\\u0644\\u0644\\u064A\\u0644. \\u0627\\u0644\\u0642\\u0637\\u0639 \\u0635\\u0648\\u062A\\u0647 \\u0639\\u0627\\u0644\\u064A: \\u0627\\u0644\\u0639\\u0645\\u0651\\u0627\\u0644 \\u0628\\u064A\\u062A\\u0648\\u0642\\u0641\\u0648\\u0627 \\u0644\\u0645\\u0627 \\u064A\\u062C\\u064A \\u062E\\u0637\\u0631 \\u0648\\u0628\\u064A\\u0631\\u062A\\u0627\\u062D\\u0648\\u0627 \\u0644\\u0645\\u0627 \\u064A\\u0646\\u0642\\u0637\\u0639 \\u0646\\u0641\\u0633\\u0647\\u0645. \\u0627\\u0644\\u062C\\u0630\\u0648\\u0639 \\u0627\\u0644\\u0645\\u0642\\u0637\\u0648\\u0639\\u0629 \\u0645\\u0645\\u0643\\u0646 \\u062A\\u0646\\u062A\\u0642\\u0644 \\u0644\\u0644\\u0645\\u062E\\u0632\\u0646 \\u062A\\u0644\\u0642\\u0627\\u0626\\u064A\\u0627\\u064B.",
