    ["\\u0637\\u0628\\u0651\\u0642 \\u0639\\u0627\\u0644\\u0641\\u0631\\u0642\\u0629 \\u0643\\u0644\\u0647\\u0627"] = "Apply to whole squad",
    ["\\u0647\\u0627\\u0644\\u0639\\u0642\\u064A\\u062F\\u0629 \\u0628\\u062A\\u0646\\u0637\\u0628\\u0642 \\u0639\\u0643\\u0644 \\u0631\\u0641\\u064A\\u0642 \\u0645\\u062C\\u0646\\u0651\\u062F\\u060C \\u0648\\u0645\\u0646\\u0647\\u0645 \\u0627\\u0644\\u0645\\u062C\\u0646\\u0651\\u062F\\u064A\\u0646 \\u0627\\u0644\\u062C\\u062F\\u062F."] = "This doctrine applies to every recruited companion, including new recruits.",
    ["\\u062D\\u062F\\u0651\\u062F \\u0633\\u064A\\u0627\\u0633\\u0629 \\u0627\\u0634\\u062A\\u0628\\u0627\\u0643 \\u0648\\u062D\\u062F\\u0629 \\u0644\\u0644\\u0641\\u0631\\u064A\\u0642 \\u0643\\u0644\\u0647. \\u0641\\u062D\\u0648\\u0635\\u0627\\u062A \\u0627\\u0644\\u0646\\u064A\\u0631\\u0627\\u0646 \\u0627\\u0644\\u0635\\u062F\\u064A\\u0642\\u0629 \\u0648\\u0627\\u0644\\u0646\\u062C\\u0627\\u0629 \\u0628\\u062A\\u0636\\u0644 \\u0634\\u063A\\u0651\\u0627\\u0644\\u0629 \\u062F\\u0627\\u064A\\u0645\\u0627\\u064B."] = "Set one team-wide engagement policy. Friendly-fire and survival checks always remain active.",
    ["\\u0627\\u0644\\u062A\\u062E\\u0641\\u0651\\u064A"] = "Stealth",
    ["\\u062A\\u062C\\u0646\\u0651\\u0628 \\u0627\\u0644\\u0627\\u062D\\u062A\\u0643\\u0627\\u0643. \\u062F\\u0627\\u0641\\u0639 \\u0628\\u0633 \\u0636\\u062F \\u0647\\u062C\\u0648\\u0645 \\u0641\\u0639\\u0644\\u064A\\u060C \\u0648\\u0627\\u0633\\u062A\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0642\\u0648\\u0629 \\u0627\\u0644\\u0647\\u0627\\u062F\\u0626\\u0629 \\u0642\\u062F \\u0645\\u0627 \\u0623\\u0645\\u0643\\u0646. \\u0645\\u0627 \\u062A\\u0637\\u0644\\u0642 \\u0646\\u0627\\u0631 \\u0645\\u0646 \\u0645\\u0631\\u0643\\u0628\\u0629 \\u0623\\u0628\\u062F\\u0627\\u064B."] = "Avoid contact. Defend only against an active attack, using quiet force whenever possible. Never shoot from a vehicle.",
    ["\\u062F\\u0641\\u0627\\u0639 \\u0642\\u0631\\u064A\\u0628"] = "Close Defense",
    ["\\u0623\\u0632\\u0644 \\u0627\\u0644\\u062A\\u0647\\u062F\\u064A\\u062F\\u0627\\u062A \\u0627\\u0644\\u0642\\u0631\\u064A\\u0628\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0641\\u0631\\u064A\\u0642 \\u0628\\u062F\\u0648\\u0646 \\u0645\\u0627 \\u062A\\u0644\\u0627\\u062D\\u0642 \\u0632\\u0648\\u0645\\u0628\\u064A \\u0628\\u0639\\u064A\\u062F. \\u0627\\u0633\\u062A\\u0639\\u0645\\u0644 \\u0623\\u0641\\u0636\\u0644 \\u0633\\u0644\\u0627\\u062D \\u0645\\u062A\\u0627\\u062D. \\u0645\\u0627 \\u062A\\u0637\\u0644\\u0642 \\u0646\\u0627\\u0631 \\u0645\\u0646 \\u0645\\u0631\\u0643\\u0628\\u0629."] = "Remove threats close to the team without pursuing distant zombies. Use the best available weapon. Do not shoot from a vehicle.",
    ["\\u0641\\u0636\\u0651\\u0644 \\u0627\\u0644\\u0623\\u0633\\u0644\\u062D\\u0629 \\u0627\\u0644\\u0646\\u0627\\u0631\\u064A\\u0629\\u060C \\u0648\\u062D\\u0627\\u0641\\u0638 \\u0639\\u0627\\u0644\\u0645\\u0633\\u0627\\u0641\\u0629\\u060C \\u0648\\u0648\\u0641\\u0651\\u0631 \\u0627\\u0644\\u0630\\u062E\\u064A\\u0631\\u0629\\u060C \\u0648\\u0627\\u062F\\u0639\\u0645 \\u0627\\u0644\\u0641\\u0631\\u064A\\u0642. \\u0625\\u0637\\u0644\\u0627\\u0642 \\u0627\\u0644\\u0646\\u0627\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0631\\u0627\\u0643\\u0628 \\u0645\\u0633\\u0645\\u0648\\u062D \\u0645\\u0646 \\u0634\\u0628\\u0627\\u0643 \\u0645\\u0641\\u062A\\u0648\\u062D \\u0623\\u0648 \\u0645\\u0643\\u0633\\u0648\\u0631 \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0622\\u0645\\u0646\\u0629."] = "Prefer firearms, maintain distance, conserve fire, and support the team. Passenger fire is allowed through an open or broken window at safe speed.",
    ["\\u0627\\u0644\\u0633\\u0644\\u0627\\u062D \\u0645\\u0641\\u062A\\u0648\\u062D"] = "Weapons Free",
    ["\\u0627\\u0634\\u062A\\u0628\\u0643 \\u0645\\u0639 \\u0627\\u0644\\u062A\\u0647\\u062F\\u064A\\u062F\\u0627\\u062A \\u0627\\u0644\\u0642\\u0631\\u064A\\u0628\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0626\\u064A\\u0629 \\u0628\\u0623\\u0641\\u0636\\u0644 \\u0633\\u0644\\u0627\\u062D \\u0648\\u0645\\u0637\\u0627\\u0631\\u062F\\u0629 \\u0642\\u0635\\u064A\\u0631\\u0629. \\u0641\\u062D\\u0648\\u0635\\u0627\\u062A \\u0627\\u0644\\u0646\\u064A\\u0631\\u0627\\u0646 \\u0627\\u0644\\u0635\\u062F\\u064A\\u0642\\u0629 \\u0648\\u0627\\u0644\\u0627\\u0646\\u0633\\u062D\\u0627\\u0628 \\u0648\\u0633\\u0644\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0643\\u0628\\u0629 \\u0628\\u062A\\u0636\\u0644 \\u0645\\u0637\\u0628\\u0651\\u0642\\u0629."] = "Engage visible nearby threats with the best weapon and brief pursuit. Friendly-fire, retreat, and vehicle safety checks still apply.",
    ["\\u0627\\u0641\\u062A\\u062D \\u062D\\u0642\\u064A\\u0628\\u0629 \\u0627\\u0644\\u0631\\u0641\\u064A\\u0642"] = "Open companion inventory",
