    ["\\u0628\\u0628\\u0637\\u0621 \\u0648\\u062A\\u0623\\u0646\\u0651\\u064A. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642 \\u0631\\u062C\\u0648\\u0639 \\u0648\\u0627\\u0636\\u062D."] = "Slow and deliberate. I want a clear way back out.",
    ["\\u0645\\u0646\\u0636\\u0644 \\u0633\\u0648\\u0627 \\u0648\\u0645\\u0646\\u062A\\u062C\\u0646\\u0651\\u0628 \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0628\\u064A\\u0639\\u0631\\u0651\\u0636 \\u062D\\u062F\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0644\\u062E\\u0637\\u0631 \\u0628\\u0644\\u0627 \\u062F\\u0627\\u0639\\u064A."] = "We stay together and avoid fights that put either of us at needless risk.",
    ["\\u0645\\u0646\\u0648\\u0641\\u0651\\u0631 \\u0627\\u0644\\u0630\\u062E\\u064A\\u0631\\u0629\\u060C \\u0648\\u0645\\u0646\\u062E\\u0644\\u0651\\u064A \\u0623\\u062F\\u0648\\u0627\\u062A\\u0646\\u0627 \\u062C\\u0627\\u0647\\u0632\\u0629\\u060C \\u0648\\u0645\\u0646\\u062E\\u062A\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0631\\u0643 \\u0627\\u0644\\u0645\\u0641\\u064A\\u062F\\u0629."] = "We conserve ammunition, keep our tools ready, and choose useful fights.",
