    ["\\u0633\\u062C\\u0651\\u0644 \\u062D\\u0627\\u0648\\u064A\\u0629 \\u0645\\u062E\\u064A\\u0645 \\u0645\\u062D\\u0645\\u0651\\u0644\\u0629 \\u0641\\u064A\\u0647\\u0627 \\u0627\\u0644\\u0633\\u062D\\u0628 \\u0623\\u0648 \\u0627\\u0644\\u0625\\u064A\\u062F\\u0627\\u0639 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0639\\u064A\\u0651\\u0646 \\u0647\\u0627\\u0644\\u0634\\u063A\\u0644\\u0629."] = "Register a loaded camp container with the needed withdrawals or deposits before assigning this job.",
