    ["\\u0639\\u0645 \\u064A\\u062F\\u0641\\u0646"] = "Burying",
    ["\\u0639\\u0645 \\u064A\\u0637\\u0645\\u0651 \\u0627\\u0644\\u0642\\u0628\\u0631"] = "Filling the grave",
    ["\\u0639\\u0645 \\u064A\\u0627\\u062E\\u062F \\u0646\\u0641\\u0633\\u0647"] = "Catching breath",
    ["\\u0639\\u0645 \\u064A\\u062C\\u064A\\u0628 \\u0623\\u062F\\u0627\\u0629"] = "Fetching a tool",
    ["\\u0639\\u0645 \\u064A\\u0631\\u062C\\u0651\\u0639 \\u0627\\u0644\\u0623\\u062F\\u0627\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062A\\u0639\\u0627\\u0631\\u0629"] = "Returning the borrowed tool",
    ["\\u0639\\u0645 \\u064A\\u062C\\u064A\\u0628 \\u0645\\u0648\\u0627\\u062F"] = "Fetching materials",
