    ["\\u0623\\u0648\\u0642\\u0641 \\u0627\\u0644\\u0625\\u0646\\u062A\\u0627\\u062C \\u0645\\u0624\\u0642\\u062A\\u0627\\u064B"] = "Pause production",
    ["\\u0643\\u0645\\u0651\\u0644 \\u0627\\u0644\\u0625\\u0646\\u062A\\u0627\\u062C"] = "Resume production",
    ["\\u0623\\u0639\\u062F \\u0627\\u0644\\u0645\\u062D\\u0627\\u0648\\u0644\\u0629"] = "Retry",
    ["\\u0623\\u0644\\u063A\\u0650 \\u0623\\u0645\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062A\\u0627\\u062C"] = "Cancel production order",
    ["\\u062A\\u0644\\u063A\\u064A \\u0623\\u0645\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062A\\u0627\\u062C \\u0647\\u0627\\u062F\\u061F \\u0627\\u0644\\u0634\\u063A\\u0644 \\u0627\\u0644\\u0645\\u0646\\u062A\\u0647\\u064A \\u0628\\u064A\\u0636\\u0644 \\u0645\\u0637\\u0631\\u062D\\u0648."] = "Cancel this production order? Finished work stays where it is.",
    ["\\u0623\\u0634\\u062C\\u0627\\u0631"] = "trees",
    ["\\u0623\\u0644\\u0648\\u0627\\u062D"] = "planks",
    ["\\u0642\\u0628\\u0648\\u0631"] = "graves",
    ["\\u062C\\u062B\\u062B"] = "bodies",
    ["\\u062C\\u0645\\u0639 \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649"] = "Collect the dead",
    ["\\u062D\\u0631\\u0642 \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649"] = "Burn the dead",
    ["\\u0627\\u062E\\u062A\\u0627\\u0631 \\u0627\\u0644\\u062F\\u0641\\u0646 \\u0623\\u0648 \\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0627\\u062E\\u062A\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0646\\u0637\\u0642\\u0629 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628\\u0629. \\u0627\\u0644\\u0639\\u0627\\u0645\\u0644 \\u0628\\u064A\\u0644\\u0627\\u0642\\u064A \\u0627\\u0644\\u062C\\u062B\\u062B \\u062C\\u0648\\u0651\\u0627 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0648\\u0645\\u0646\\u0627\\u0637\\u0642 \\u0627\\u0644\\u062D\\u0637\\u0628\\u060C \\u0648\\u0628\\u064A\\u0633\\u062D\\u0628\\u0647\\u0627 \\u0644\\u0647\\u0646\\u0627\\u0643\\u060C \\u0648\\u0628\\u064A\\u062F\\u0641\\u0646\\u0647\\u0627 \\u0623\\u0648 \\u0628\\u064A\\u062D\\u0631\\u0642\\u0647\\u0627. \\u0627\\u0644\\u0631\\u0641\\u0627\\u0642 \\u0627\\u0644\\u0644\\u064A \\u0633\\u0642\\u0637\\u0648\\u0627 \\u0628\\u064A\\u0646\\u0631\\u062F\\u0641\\u0646\\u0648\\u0627 \\u062F\\u0627\\u064A\\u0645\\u0627\\u064B \\u0628\\u0642\\u0628\\u0631 \\u0628\\u0627\\u0633\\u0645\\u0647\\u0645 \\u0645\\u0627 \\u0628\\u064A\\u0646\\u062D\\u0631\\u0642\\u0648\\u0627 \\u0623\\u0628\\u062F\\u0627\\u064B. \\u0627\\u0644\\u0639\\u0627\\u0645\\u0644 \\u0628\\u064A\\u062A\\u0631\\u0643 \\u0627\\u0644\\u062C\\u062B\\u0629 \\u0641\\u0648\\u0631\\u0627\\u064B \\u0644\\u0645\\u0627 \\u064A\\u0638\\u0647\\u0631 \\u062E\\u0637\\u0631."] = "Choose burial or pyre, then choose the matching area. The worker finds bodies inside the camp and lumber areas, drags them there, and buries or burns them. Fallen companions are always buried in their own named grave, never burned. A worker drops the body at once when danger appears.",
    ["\\u0628\\u064A\\u062D\\u0631\\u0642 \\u0627\\u0644\\u062C\\u062B\\u062B \\u0627\\u0644\\u0645\\u0648\\u0636\\u0648\\u0639\\u0629 \\u0639\\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629 \\u0627\\u0644\\u0645\\u062E\\u062A\\u0627\\u0631\\u0629 \\u0628\\u0623\\u064A \\u0623\\u062F\\u0627\\u0629 \\u0625\\u0634\\u0639\\u0627\\u0644 \\u0635\\u0627\\u0644\\u062D\\u0629 \\u0648\\u0639\\u0628\\u0648\\u0629 \\u0628\\u0646\\u0632\\u064A\\u0646 \\u0645\\u0646 \\u0645\\u062E\\u0632\\u0646 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645. \\u0627\\u0644\\u062D\\u0631\\u0642 \\u0646\\u0627\\u0631 \\u062D\\u0642\\u064A\\u0642\\u064A\\u0629: \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0643\\u0648\\u0646 \\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629 \\u0628\\u0631\\u0651\\u0627 \\u0648\\u0628\\u0639\\u064A\\u062F\\u0629 \\u0639\\u0646 \\u0627\\u0644\\u0645\\u0628\\u0627\\u0646\\u064A \\u0648\\u0627\\u0644\\u0623\\u0634\\u062C\\u0627\\u0631 \\u0648\\u0627\\u0644\\u0628\\u0636\\u0627\\u0626\\u0639 \\u0627\\u0644\\u0645\\u062E\\u0632\\u0651\\u0646\\u0629. \\u0645\\u0627 \\u0628\\u064A\\u0646\\u0634\\u0639\\u0644 \\u0634\\u064A \\u0628\\u0627\\u0644\\u0645\\u0637\\u0631\\u060C \\u0648\\u0643\\u0644 \\u0639\\u0627\\u0645\\u0644 \\u0628\\u064A\\u0648\\u0642\\u0641 \\u0625\\u0630\\u0627 \\u0627\\u0646\\u062A\\u0634\\u0631\\u062A \\u0627\\u0644\\u0646\\u0627\\u0631."] = "Burns bodies lying on the chosen pyre with any usable firestarter and a petrol can from camp storage. Burning is real fire: the pyre must be outdoors and clear of buildings, trees and stored goods. Nothing is lit in rain, and every worker stops if the fire spreads.",
    ["\\u0645\\u0646\\u0627\\u0637\\u0642 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0648\\u0627\\u0644\\u062D\\u0637\\u0628"] = "Camp and lumber areas",
    ["\\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0628\\u0633"] = "Camp only",
    ["\\u0645\\u0646\\u0627\\u0637\\u0642 \\u0627\\u0644\\u062D\\u0637\\u0628 \\u0628\\u0633"] = "Lumber areas only",
    ["\\u062A\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639\\u0647\\u0627 \\u0645\\u0639 \\u0623\\u063A\\u0631\\u0627\\u0636\\u0647\\u0627"] = "Handle them with their belongings",
    ["\\u0627\\u0644\\u062D\\u0631\\u0642 \\u0628\\u064A\\u0634\\u0639\\u0644 \\u0646\\u0627\\u0631 \\u062D\\u0642\\u064A\\u0642\\u064A\\u0629 \\u0645\\u0645\\u0643\\u0646 \\u062A\\u0646\\u062A\\u0634\\u0631 \\u0644\\u0645\\u0627 \\u064A\\u0643\\u0648\\u0646 \\u062E\\u064A\\u0627\\u0631 \\u0627\\u0646\\u062A\\u0634\\u0627\\u0631 \\u0627\\u0644\\u0646\\u0627\\u0631 \\u0645\\u0641\\u0639\\u0651\\u0644. \\u0627\\u0628\\u0639\\u062F \\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629 \\u0639\\u0646 \\u0623\\u064A \\u0634\\u064A \\u0628\\u062F\\u0643 \\u062A\\u062D\\u062A\\u0641\\u0638 \\u0641\\u064A\\u0647."] = "Burning starts a real fire that can spread when the Fire Spread sandbox option is on. Keep the pyre away from anything you want to keep.",
    ["\\u0639\\u0645 \\u064A\\u0645\\u0633\\u0643 \\u062C\\u062B\\u0629"] = "Taking hold of a body",
    ["\\u0639\\u0645 \\u064A\\u0633\\u062D\\u0628 \\u062C\\u062B\\u0629"] = "Dragging a body",
    ["\\u0639\\u0645 \\u064A\\u062D\\u0637 \\u062C\\u062B\\u0629"] = "Laying a body down",
    ["\\u0639\\u0645 \\u064A\\u0634\\u0639\\u0644 \\u0627\\u0644\\u0645\\u062D\\u0631\\u0642\\u0629"] = "Lighting the pyre",
    ["\\u0639\\u0645 \\u064A\\u0631\\u0627\\u0642\\u0628 \\u0627\\u0644\\u0646\\u0627\\u0631"] = "Watching the fire",
    ["\\u0645\\u0627 \\u0628\\u062A\\u0646\\u0642\\u0631\\u0627 \\u0635\\u0641\\u062D\\u0627\\u062A \\u0647\\u0627\\u0644\\u0645\\u0630\\u0643\\u0651\\u0631\\u0627\\u062A."] = "The pages of this diary cannot be read.",
    ["\\u0627\\u0644\\u0635\\u0641\\u062D\\u0627\\u062A \\u0644\\u0633\\u0627 \\u0641\\u0627\\u0636\\u064A\\u0629."] = "The pages are still blank.",
    ["A-"] = "A-",
    ["A+"] = "A+",
    ["\\u0635\\u0641\\u062D\\u0629 \\u0644\\u0641\\u0648\\u0642"] = "Page up",
    ["\\u0635\\u0641\\u062D\\u0629 \\u0644\\u062A\\u062D\\u062A"] = "Page down",
    ["\\u0633\\u0643\\u0651\\u0631"] = "Close",
    ["\\u0627\\u0639\\u0637\\u064A \\u0644\\u0642\\u0628..."] = "Give nickname...",
    ["\\u0634\\u064A\\u0644 \\u0627\\u0644\\u0644\\u0642\\u0628"] = "Clear nickname",
    ["\\u0627\\u0639\\u0637\\u064A \\u0644\\u0642\\u0628"] = "Give nickname",
    ["\\u0627\\u0633\\u062A\\u0639\\u0645\\u0644 \\u0645\\u0646 2 \\u0644\\u064016 \\u062D\\u0631\\u0641 \\u0623\\u0648 \\u0631\\u0642\\u0645 \\u0623\\u0648 \\u0645\\u0633\\u0627\\u0641\\u0629 \\u0623\\u0648 \\u0641\\u0627\\u0635\\u0644\\u0629 \\u0639\\u0644\\u064A\\u0627 \\u0623\\u0648 \\u0634\\u0631\\u0637\\u0629 \\u0623\\u0648 \\u0646\\u0642\\u0637\\u0629."] = "Use 2-16 letters, numbers, spaces, apostrophes, hyphens or periods.",
    ["\\u0627\\u0639\\u0631\\u0636 \\u0627\\u0644\\u0623\\u0644\\u0642\\u0627\\u0628"] = "Show nicknames",
    ["\\u062D\\u0643\\u064A \\u0627\\u0644\\u0631\\u0641\\u064A\\u0642"] = "Companion chatter",
    ["\\u0643\\u0644 \\u0642\\u062F\\u064A\\u0634 \\u0628\\u064A\\u062D\\u0643\\u064A \\u0627\\u0644\\u0631\\u0641\\u0627\\u0642 \\u0645\\u0646 \\u062D\\u0627\\u0644\\u0647\\u0645. \\u00AB\\u0623\\u0642\\u0644\\u00BB \\u0628\\u064A\\u0636\\u0627\\u0639\\u0641 \\u0641\\u062A\\u0631\\u0629 \\u0627\\u0644\\u0627\\u0646\\u062A\\u0638\\u0627\\u0631 \\u0627\\u0644\\u0639\\u0627\\u062F\\u064A\\u0629\\u061B \\u0648\\u00AB\\u0646\\u0627\\u062F\\u0631\\u00BB \\u0628\\u064A\\u0636\\u0631\\u0628\\u0647\\u0627 \\u0628\\u0623\\u0631\\u0628\\u0639\\u0629."] = "How often companions speak on their own. Less doubles the normal cooldown; Rare quadruples it.",
    ["\\u0627\\u0644\\u0633\\u0639\\u0627\\u0644 \\u0648\\u0627\\u0644\\u0639\\u0637\\u0633"] = "Coughs and sneezes",
    ["\\u00AB\\u0639\\u0627\\u062F\\u064A\\u00BB \\u0628\\u064A\\u0633\\u0645\\u062D \\u0628\\u0635\\u0648\\u062A \\u0645\\u0631\\u0629 \\u0628\\u0627\\u0644\\u062F\\u0642\\u064A\\u0642\\u0629 \\u0627\\u0644\\u062D\\u0642\\u064A\\u0642\\u064A\\u0629 \\u0639\\u0627\\u0644\\u0623\\u0643\\u062A\\u0631\\u061B \\u0648\\u00AB\\u0646\\u0627\\u062F\\u0631\\u00BB \\u0645\\u0631\\u0629 \\u0643\\u0644 \\u062E\\u0645\\u0633 \\u062F\\u0642\\u0627\\u064A\\u0642 \\u062D\\u0642\\u064A\\u0642\\u064A\\u0629 \\u0639\\u0627\\u0644\\u0623\\u0643\\u062A\\u0631\\u061B \\u0648\\u00AB\\u0645\\u0637\\u0641\\u064A\\u00BB \\u0628\\u064A\\u0633\\u0643\\u0651\\u062A \\u0627\\u0644\\u0633\\u0639\\u0627\\u0644 \\u0648\\u0627\\u0644\\u0639\\u0637\\u0633 \\u0627\\u0644\\u0623\\u0635\\u0644\\u064A \\u0648\\u0627\\u0644\\u062A\\u062C\\u0645\\u064A\\u0644\\u064A."] = "Normal allows a sound at most once per real minute; Rare at most once per five real minutes; Off silences both native and cosmetic coughs and sneezes.",
    ["\\u0627\\u0644\\u0632\\u0643\\u0627\\u0645 \\u0627\\u0644\\u0639\\u0627\\u062F\\u064A"] = "Ordinary colds",
    ["\\u0637\\u0641\\u0651\\u064A \\u0627\\u0644\\u0632\\u0643\\u0627\\u0645 \\u0627\\u0644\\u0639\\u0627\\u062F\\u064A \\u0644\\u0644\\u0631\\u0641\\u0627\\u0642. \\u0639\\u062F\\u0648\\u0649 \\u0646\\u0648\\u0643\\u0633 \\u0648\\u062A\\u0623\\u062B\\u064A\\u0631\\u0627\\u062A \\u0627\\u0644\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062A\\u0627\\u0646\\u064A\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u062A\\u063A\\u064A\\u0651\\u0631."] = "Turn off ordinary colds for companions. Knox infection and other illness effects are unchanged.",
    ["\\u0627\\u062D\\u0645\\u064A \\u0627\\u0644\\u0645\\u062C\\u0646\\u0651\\u062F\\u064A\\u0646 \\u0645\\u0646 \\u0636\\u0631\\u0628\\u0627\\u062A\\u0643"] = "Protect recruits from your attacks",
    ["\\u0628\\u064A\\u0645\\u0646\\u0639 \\u0636\\u0631\\u0628\\u0627\\u062A\\u0643 \\u0645\\u0646 \\u0625\\u064A\\u0630\\u0627\\u0621 \\u0627\\u0644\\u0631\\u0641\\u0627\\u0642 \\u0627\\u0644\\u0645\\u062C\\u0646\\u0651\\u062F\\u064A\\u0646. \\u0645\\u0637\\u0641\\u064A \\u0627\\u0641\\u062A\\u0631\\u0627\\u0636\\u064A\\u0627\\u064B."] = "Prevents your attacks from damaging recruited companions. Off by default.",
    ["\\u0639\\u0627\\u062F\\u064A"] = "Normal",
    ["\\u0623\\u0642\\u0644"] = "Less",
    ["\\u0645\\u0637\\u0641\\u064A"] = "Off",
    ["\\u0641\\u0631\\u0651\\u063A \\u0627\\u0644\\u0633\\u064A\\u0627\\u0631\\u0627\\u062A \\u0627\\u0644\\u0645\\u0631\\u0643\\u0648\\u0646\\u0629 \\u062A\\u0644\\u0642\\u0627\\u0626\\u064A\\u0627\\u064B"] = "Unload parked cars automatically",
    ["\\u0627\\u0644\\u0633\\u064A\\u0627\\u0631\\u0627\\u062A \\u0627\\u0644\\u0645\\u0631\\u0643\\u0648\\u0646\\u0629"] = "Parked cars",
    ["\\u0641\\u0631\\u0651\\u063A \\u0644\\u0644\\u0642\\u0627\\u0639\\u062F\\u0629"] = "Unload to base",
    ["\\u0627\\u0646\\u0636\\u0627\\u0641 \\u062A\\u0641\\u0631\\u064A\\u063A \\u0627\\u0644\\u0633\\u064A\\u0627\\u0631\\u0629 \\u0644\\u0634\\u063A\\u0644\\u0627\\u062A \\u0627\\u0644\\u0642\\u0627\\u0639\\u062F\\u0629"] = "Car unloading added to base jobs",
}
