    ["I need a plank."] = "\\u0628\\u062F\\u064A \\u0644\\u0648\\u062D \\u062E\\u0634\\u0628.",
    ["I need two nails."] = "\\u0628\\u062F\\u064A \\u0645\\u0633\\u0645\\u0627\\u0631\\u064A\\u0646.",
    ["I need an unbroken saw."] = "\\u0628\\u062F\\u064A \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0633\\u0644\\u064A\\u0645.",
    ["I need an unbroken screwdriver."] = "\\u0628\\u062F\\u064A \\u0645\\u0641\\u0643 \\u0633\\u0644\\u064A\\u0645.",
    ["I need a fueled blowtorch."] = "\\u0628\\u062F\\u064A \\u0644\\u062D\\u0651\\u0627\\u0645 \\u0641\\u064A\\u0647 \\u0648\\u0642\\u0648\\u062F.",
    ["I need a tool that can remove barricades."] = "\\u0628\\u062F\\u064A \\u0623\\u062F\\u0627\\u0629 \\u0628\\u062A\\u0634\\u064A\\u0644 \\u0627\\u0644\\u0645\\u062A\\u0627\\u0631\\u064A\\u0633.",
    ["I need to finish what I'm doing first."] = "\\u0644\\u0627\\u0632\\u0645 \\u062E\\u0644\\u0651\\u0635 \\u0627\\u0644\\u0644\\u064A \\u0639\\u0645 \\u0628\\u0639\\u0645\\u0644\\u0647 \\u0623\\u0648\\u0644.",
    ["You asked me to come with you. I remember deciding I did not want to face this alone."] = "\\u0625\\u0646\\u062A \\u0637\\u0644\\u0628\\u062A \\u0645\\u0646\\u064A \\u0625\\u062C\\u064A \\u0645\\u0639\\u0643. \\u0628\\u062A\\u0630\\u0643\\u0651\\u0631 \\u0625\\u0646\\u064A \\u0642\\u0631\\u0631\\u062A \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0648\\u0627\\u062C\\u0647 \\u0647\\u0627\\u0644\\u0634\\u064A \\u0644\\u062D\\u0627\\u0644\\u064A.",
    ["You stayed close when I was hurt and helped me get patched up."] = "\\u0636\\u0644\\u064A\\u062A \\u062C\\u0646\\u0628\\u064A \\u0644\\u0645\\u0627 \\u0627\\u0646\\u062C\\u0631\\u062D\\u062A \\u0648\\u0633\\u0627\\u0639\\u062F\\u062A\\u0646\\u064A \\u0636\\u0645\\u0651\\u062F \\u062C\\u0631\\u0648\\u062D\\u064A.",
    ["You made sure I had something to eat when I needed it."] = "\\u062A\\u0623\\u0643\\u062F\\u062A \\u0625\\u0646\\u0648 \\u0639\\u0646\\u062F\\u064A \\u0634\\u064A \\u0622\\u0643\\u0644\\u0647 \\u0644\\u0645\\u0627 \\u0643\\u0646\\u062A \\u0645\\u062D\\u062A\\u0627\\u062C\\u0629.",
    ["You made sure I had water when I was running dry."] = "\\u062A\\u0623\\u0643\\u062F\\u062A \\u0625\\u0646\\u0648 \\u0639\\u0646\\u062F\\u064A \\u0645\\u064A \\u0644\\u0645\\u0627 \\u0643\\u0646\\u062A \\u0639\\u0637\\u0634\\u0627\\u0646\\u0629 \\u0643\\u062A\\u064A\\u0631.",
    ["We got out together when things were closing in. I have not forgotten that."] = "\\u0637\\u0644\\u0639\\u0646\\u0627 \\u0633\\u0648\\u0627 \\u0644\\u0645\\u0627 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0636\\u0627\\u0642\\u062A \\u0639\\u0644\\u064A\\u0646\\u0627. \\u0645\\u0627 \\u0646\\u0633\\u064A\\u062A \\u0647\\u0627\\u062F.",
    ["I helped pull the danger away from you. We made it through."] = "\\u0633\\u0627\\u0639\\u062F\\u062A \\u0623\\u0628\\u0639\\u062F \\u0627\\u0644\\u062E\\u0637\\u0631 \\u0639\\u0646\\u0643. \\u0639\\u062F\\u0651\\u064A\\u0646\\u0627\\u0647\\u0627 \\u0633\\u0648\\u0627.",
    ["I got hurt while we were together. I was scared, but you did not leave."] = "\\u0627\\u0646\\u062C\\u0631\\u062D\\u062A \\u0648\\u0625\\u062D\\u0646\\u0627 \\u0633\\u0648\\u0627. \\u0643\\u0646\\u062A \\u062E\\u0627\\u064A\\u0641\\u0629\\u060C \\u0628\\u0633 \\u0625\\u0646\\u062A \\u0645\\u0627 \\u062A\\u0631\\u0643\\u062A\\u0646\\u064A.",
    ["You were hurt, and I did what I could to help you."] = "\\u0625\\u0646\\u062A \\u0627\\u0646\\u062C\\u0631\\u062D\\u062A\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645\\u0644\\u062A \\u0627\\u0644\\u0644\\u064A \\u0628\\u0642\\u062F\\u0631 \\u0639\\u0644\\u064A\\u0647 \\u0644\\u0633\\u0627\\u0639\\u062F\\u0643.",
    ["You took the time to ask who I was before all this."] = "\\u062E\\u0635\\u0651\\u0635\\u062A \\u0648\\u0642\\u062A \\u0644\\u062A\\u0633\\u0623\\u0644\\u0646\\u064A \\u0645\\u064A\\u0646 \\u0643\\u0646\\u062A \\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F.",
    ["I remember us getting through another day together."] = "\\u0628\\u062A\\u0630\\u0643\\u0651\\u0631 \\u0643\\u064A\\u0641 \\u0639\\u062F\\u0651\\u064A\\u0646\\u0627 \\u064A\\u0648\\u0645 \\u062A\\u0627\\u0646\\u064A \\u0633\\u0648\\u0627.",
    ["I used the quiet time to keep our gear and supplies in shape."] = "\\u0627\\u0633\\u062A\\u063A\\u0644\\u064A\\u062A \\u0627\\u0644\\u0647\\u062F\\u0648\\u0621 \\u0644\\u0623\\u062D\\u0627\\u0641\\u0638 \\u0639\\u0644\\u0649 \\u0639\\u062A\\u0627\\u062F\\u0646\\u0627 \\u0648\\u0645\\u0624\\u0646\\u0646\\u0627.",
    ["%1 died. I keep thinking about the time we had together."] = "%1 \\u0645\\u0627\\u062A. \\u0645\\u0627 \\u0639\\u0645 \\u0628\\u0637\\u0651\\u0644 \\u0641\\u0643\\u0651\\u0631 \\u0628\\u0627\\u0644\\u0648\\u0642\\u062A \\u0627\\u0644\\u0644\\u064A \\u0642\\u0636\\u064A\\u0646\\u0627\\u0647 \\u0633\\u0648\\u0627.",
    ["I am not all right yet. %1 is gone, and I need time."] = "\\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D\\u0629. %1 \\u0631\\u0627\\u062D\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0628\\u062F\\u064A \\u0648\\u0642\\u062A.",
    ["I need you to know something is wrong. It feels like Knox symptoms."] = "\\u0628\\u062F\\u064A \\u064A\\u0627\\u0643 \\u062A\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0648 \\u0641\\u064A \\u0634\\u064A \\u063A\\u0644\\u0637. \\u062D\\u0627\\u0633\\u0629 \\u0625\\u0646\\u0647\\u0627 \\u0623\\u0639\\u0631\\u0627\\u0636 \\u0646\\u0648\\u0643\\u0633.",
    ["I need treatment and a clean bandage."] = "\\u0628\\u062F\\u064A \\u0639\\u0644\\u0627\\u062C \\u0648\\u0636\\u0645\\u0627\\u062F\\u0629 \\u0646\\u0636\\u064A\\u0641\\u0629.",
    ["Water, if we can spare it. I am getting very thirsty."] = "\\u0645\\u064A\\u060C \\u0625\\u0630\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0648\\u0641\\u0651\\u0631. \\u0639\\u0637\\u0634\\u0627\\u0646\\u0629 \\u0643\\u062A\\u064A\\u0631.",
    ["Food would help. I am running on empty."] = "\\u0627\\u0644\\u0623\\u0643\\u0644 \\u0628\\u064A\\u0641\\u064A\\u062F. \\u0623\\u0646\\u0627 \\u0641\\u0627\\u0636\\u064A\\u0629.",
    ["I need a quiet minute somewhere safe."] = "\\u0628\\u062F\\u064A \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0647\\u062F\\u0648\\u0621 \\u0628\\u0645\\u0643\\u0627\\u0646 \\u0622\\u0645\\u0646.",
    ["We should find clean bandages before someone needs one."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0636\\u0645\\u0627\\u062F\\u0627\\u062A \\u0646\\u0636\\u064A\\u0641\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u062D\\u062A\\u0627\\u062C\\u0647\\u0627.",
    ["Room clear."] = "\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0641\\u0627\\u0636\\u064A\\u0629.",
    ["Contact - one infected."] = "\\u0627\\u062D\\u062A\\u0643\\u0627\\u0643 \\u2014 \\u0645\\u0635\\u0627\\u0628 \\u0648\\u0627\\u062D\\u062F.",
    ["Multiple contacts."] = "\\u0641\\u064A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0645\\u0635\\u0627\\u0628.",
    ["Can't verify the whole room."] = "\\u0645\\u0627 \\u0642\\u062F\\u0631\\u062A \\u0623\\u062A\\u0623\\u0643\\u062F \\u0645\\u0646 \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0643\\u0644\\u0647\\u0627.",
    ["I am short on ammunition. I will save what I have."] = "\\u0630\\u062E\\u064A\\u0631\\u062A\\u064A \\u0642\\u0644\\u064A\\u0644\\u0629. \\u0631\\u062D \\u0648\\u0641\\u0651\\u0631 \\u0627\\u0644\\u0644\\u064A \\u0639\\u0646\\u062F\\u064A.",
    ["I am all right for now. Ready when you are."] = "\\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629 \\u0647\\u0644\\u0623. \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0648\\u0642\\u062A \\u0645\\u0627 \\u062A\\u0643\\u0648\\u0646 \\u062C\\u0627\\u0647\\u0632.",
    ["Maybe another time. Some things are still hard to talk about."] = "\\u064A\\u0645\\u0643\\u0646 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0641\\u064A \\u0623\\u0634\\u064A\\u0627\\u0621 \\u0644\\u0633\\u0627 \\u0635\\u0639\\u0628 \\u0623\\u062D\\u0643\\u064A \\u0639\\u0646\\u0647\\u0627.",
    ["Physically I am okay. I am still trying to settle my nerves."] = "\\u062C\\u0633\\u062F\\u064A\\u0627\\u064B \\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u062D\\u0627\\u0648\\u0644 \\u0623\\u0647\\u062F\\u0651\\u064A \\u0623\\u0639\\u0635\\u0627\\u0628\\u064A.",
    ["I am holding up. Better with someone watching my back."] = "\\u0639\\u0645 \\u0635\\u0645\\u062F. \\u0623\\u062D\\u0633\\u0646 \\u0644\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u062D\\u0645\\u064A \\u0638\\u0647\\u0631\\u064A.",
    ["We are pushing our luck. I want a clear way out before we go farther."] = "\\u0639\\u0645 \\u0646\\u062C\\u0631\\u0651\\u0628 \\u062D\\u0638\\u0651\\u0646\\u0627. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642 \\u062E\\u0631\\u0648\\u062C \\u0648\\u0627\\u0636\\u062D \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0628\\u0639\\u062F \\u0623\\u0643\\u062A\\u0631.",
    ["This position can work, but I am keeping an eye on the exits."] = "\\u0647\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0645\\u0645\\u0643\\u0646 \\u064A\\u0645\\u0634\\u064A\\u060C \\u0628\\u0633 \\u0639\\u064A\\u0646\\u064A \\u0639\\u0627\\u0644\\u0645\\u062E\\u0627\\u0631\\u062C.",
    ["I can search as we move. I will leave anything you have already claimed alone."] = "\\u0641\\u064A\\u0646\\u064A \\u0641\\u062A\\u0651\\u0634 \\u0648\\u0625\\u062D\\u0646\\u0627 \\u0645\\u0627\\u0634\\u064A\\u064A\\u0646. \\u0631\\u062D \\u0623\\u062A\\u0631\\u0643 \\u0623\\u064A \\u0634\\u064A \\u0625\\u0646\\u062A \\u062D\\u062C\\u0632\\u062A\\u0647.",
    ["Slow and deliberate. We do not need to win every fight."] = "\\u0628\\u0628\\u0637\\u0621 \\u0648\\u062A\\u0623\\u0646\\u0651\\u064A. \\u0645\\u0648 \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0643\\u0633\\u0628 \\u0643\\u0644 \\u0645\\u0639\\u0631\\u0643\\u0629.",
    ["I heard you. Give me a minute to breathe."] = "\\u0633\\u0645\\u0639\\u062A\\u0643. \\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0623\\u062A\\u0646\\u0641\\u0651\\u0633.",
    ["I am good. Save that speech for when one of us really needs it."] = "\\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u062E\\u0644\\u0651\\u064A \\u0647\\u0627\\u0644\\u0643\\u0644\\u0627\\u0645 \\u0644\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u064A\\u062D\\u062A\\u0627\\u062C\\u0647 \\u0641\\u0639\\u0644\\u0627\\u064B.",
    ["Thank you. I needed to hear that."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0643\\u0646\\u062A \\u0645\\u062D\\u062A\\u0627\\u062C\\u0629 \\u0627\\u0633\\u0645\\u0639 \\u0647\\u0627\\u062F.",
    ["Thanks, but let us save the celebration until the work is done."] = "\\u0634\\u0643\\u0631\\u0627\\u064B\\u060C \\u0628\\u0633 \\u062E\\u0644\\u0651\\u064A\\u0646\\u0627 \\u0646\\u0623\\u062C\\u0651\\u0644 \\u0627\\u0644\\u0627\\u062D\\u062A\\u0641\\u0627\\u0644 \\u0644\\u062D\\u062F \\u0645\\u0627 \\u0646\\u062E\\u0644\\u0651\\u0635 \\u0627\\u0644\\u0634\\u063A\\u0644.",
    ["That means more than you know."] = "\\u0647\\u0627\\u062F \\u0628\\u064A\\u0639\\u0646\\u064A \\u0625\\u0644\\u064A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0645\\u0627 \\u0628\\u062A\\u062A\\u062E\\u064A\\u0644.",
    ["I am still getting to know you. Give me time."] = "\\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0628\\u062A\\u0639\\u0631\\u0651\\u0641 \\u0639\\u0644\\u064A\\u0643. \\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u0648\\u0642\\u062A.",
    ["We work well together. Trust takes time, but we are getting there."] = "\\u0645\\u0646\\u0634\\u062A\\u063A\\u0644 \\u0645\\u0646\\u064A\\u062D \\u0633\\u0648\\u0627. \\u0627\\u0644\\u062B\\u0642\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0648\\u0642\\u062A\\u060C \\u0628\\u0633 \\u0639\\u0645 \\u0646\\u0648\\u0635\\u0644.",
    ["We have been through enough that I know you will be there."] = "\\u0645\\u0631\\u0651\\u064A\\u0646\\u0627 \\u0628\\u0645\\u0627 \\u064A\\u0643\\u0641\\u064A \\u0644\\u0623\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0643 \\u0631\\u062D \\u062A\\u0643\\u0648\\u0646 \\u0645\\u0648\\u062C\\u0648\\u062F.",
    ["I trust you with my life. That is not something I say lightly."] = "\\u0628\\u0623\\u062A\\u0645\\u0646\\u0643 \\u0639\\u062D\\u064A\\u0627\\u062A\\u064A. \\u0647\\u0627\\u062F \\u0645\\u0648 \\u0643\\u0644\\u0627\\u0645 \\u0628\\u0642\\u0648\\u0644\\u0647 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629.",
    ["You are family to me now. I am not walking away."] = "\\u0635\\u0631\\u062A \\u0639\\u064A\\u0644\\u062A\\u064A. \\u0645\\u0627 \\u0631\\u062D \\u0623\\u0645\\u0634\\u064A.",
    ["Before this, I worked as a paramedic."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0645\\u0633\\u0639\\u0641\\u0629.",
    ["Before this, I worked as a mechanic."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0645\\u064A\\u0643\\u0627\\u0646\\u064A\\u0643\\u064A\\u0629.",
    ["Before this, I worked as a teacher."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0645\\u0639\\u0644\\u0651\\u0645\\u0629.",
    ["Before this, I worked as a carpenter."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0646\\u062C\\u0651\\u0627\\u0631\\u0629.",
    ["Before this, I worked as a cook."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0637\\u0628\\u0651\\u0627\\u062E\\u0629.",
    ["Before this, I worked as a park ranger."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u062D\\u0627\\u0631\\u0633\\u0629 \\u0645\\u062D\\u0645\\u064A\\u0629.",
    ["Before this, I worked as a nurse."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0645\\u0645\\u0631\\u0651\\u0636\\u0629.",
    ["Before this, I worked as an electrician."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0643\\u0647\\u0631\\u0628\\u0627\\u0626\\u064A\\u0629.",
    ["Before this, I worked in a warehouse."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0627\\u0634\\u062A\\u063A\\u0644 \\u0628\\u0645\\u0633\\u062A\\u0648\\u062F\\u0639.",
    ["Before this, I worked as a librarian."] = "\\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0643\\u0646\\u062A \\u0623\\u0645\\u064A\\u0646\\u0629 \\u0645\\u0643\\u062A\\u0628\\u0629.",
    ["I was living around Muldraugh when it started."] = "\\u0643\\u0646\\u062A \\u0639\\u0627\\u064A\\u0634\\u0629 \\u062D\\u0648\\u0627\\u0644\\u064A\\u0646 \\u0645\\u0648\\u0644\\u062F\\u0631\\u0627\\u0641 \\u0644\\u0645\\u0627 \\u0628\\u062F\\u0623 \\u0643\\u0644 \\u0647\\u0627\\u062F.",
    ["I was living around Rosewood when it started."] = "\\u0643\\u0646\\u062A \\u0639\\u0627\\u064A\\u0634\\u0629 \\u062D\\u0648\\u0627\\u0644\\u064A\\u0646 \\u0631\\u0648\\u0632\\u0648\\u0648\\u062F \\u0644\\u0645\\u0627 \\u0628\\u062F\\u0623 \\u0643\\u0644 \\u0647\\u0627\\u062F.",
    ["I was living around Riverside when it started."] = "\\u0643\\u0646\\u062A \\u0639\\u0627\\u064A\\u0634\\u0629 \\u062D\\u0648\\u0627\\u0644\\u064A\\u0646 \\u0631\\u064A\\u0641\\u0631\\u0633\\u0627\\u064A\\u062F \\u0644\\u0645\\u0627 \\u0628\\u062F\\u0623 \\u0643\\u0644 \\u0647\\u0627\\u062F.",
    ["I was living around West Point when it started."] = "\\u0643\\u0646\\u062A \\u0639\\u0627\\u064A\\u0634\\u0629 \\u062D\\u0648\\u0627\\u0644\\u064A\\u0646 \\u0648\\u064A\\u0633\\u062A \\u0628\\u0648\\u064A\\u0646\\u062A \\u0644\\u0645\\u0627 \\u0628\\u062F\\u0623 \\u0643\\u0644 \\u0647\\u0627\\u062F.",
    ["I was living on the Louisville outskirts when it started."] = "\\u0643\\u0646\\u062A \\u0639\\u0627\\u064A\\u0634\\u0629 \\u0628\\u0636\\u0648\\u0627\\u062D\\u064A \\u0644\\u0648\\u064A\\u0633\\u0641\\u064A\\u0644 \\u0644\\u0645\\u0627 \\u0628\\u062F\\u0623 \\u0643\\u0644 \\u0647\\u0627\\u062F.",
    ["I was living around Brandenburg when it started."] = "\\u0643\\u0646\\u062A \\u0639\\u0627\\u064A\\u0634\\u0629 \\u062D\\u0648\\u0627\\u0644\\u064A\\u0646 \\u0628\\u0631\\u0627\\u0646\\u062F\\u0646\\u0628\\u0648\\u0631\\u063A \\u0644\\u0645\\u0627 \\u0628\\u062F\\u0623 \\u0643\\u0644 \\u0647\\u0627\\u062F.",
    ["The thing I try not to lose is honesty."] = "\\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0644\\u064A \\u0628\\u062D\\u0627\\u0648\\u0644 \\u0645\\u0627 \\u0623\\u062E\\u0633\\u0631\\u0647 \\u0647\\u0648 \\u0627\\u0644\\u0635\\u062F\\u0642.",
    ["The thing I try not to lose is loyalty."] = "\\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0644\\u064A \\u0628\\u062D\\u0627\\u0648\\u0644 \\u0645\\u0627 \\u0623\\u062E\\u0633\\u0631\\u0647 \\u0647\\u0648 \\u0627\\u0644\\u0648\\u0641\\u0627\\u0621.",
    ["The thing I try not to lose is kindness."] = "\\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0644\\u064A \\u0628\\u062D\\u0627\\u0648\\u0644 \\u0645\\u0627 \\u0623\\u062E\\u0633\\u0631\\u0647 \\u0647\\u0648 \\u0627\\u0644\\u0637\\u064A\\u0628\\u0629.",
    ["The thing I try not to lose is self-reliance."] = "\\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0644\\u064A \\u0628\\u062D\\u0627\\u0648\\u0644 \\u0645\\u0627 \\u0623\\u062E\\u0633\\u0631\\u0647 \\u0647\\u0648 \\u0627\\u0644\\u0627\\u0639\\u062A\\u0645\\u0627\\u062F \\u0639\\u0627\\u0644\\u0646\\u0641\\u0633.",
    ["The thing I try not to lose is a sense of community."] = "\\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0644\\u064A \\u0628\\u062D\\u0627\\u0648\\u0644 \\u0645\\u0627 \\u0623\\u062E\\u0633\\u0631\\u0647 \\u0647\\u0648 \\u0627\\u0644\\u0625\\u062D\\u0633\\u0627\\u0633 \\u0628\\u0627\\u0644\\u062C\\u0645\\u0627\\u0639\\u0629.",
    ["The thing I try not to lose is courage."] = "\\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0644\\u064A \\u0628\\u062D\\u0627\\u0648\\u0644 \\u0645\\u0627 \\u0623\\u062E\\u0633\\u0631\\u0647 \\u0647\\u0648 \\u0627\\u0644\\u0634\\u062C\\u0627\\u0639\\u0629.",
    ["What scares me most is ending up alone."] = "\\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0628\\u064A\\u062E\\u0648\\u0651\\u0641\\u0646\\u064A \\u0625\\u0646\\u064A \\u0623\\u0636\\u0644 \\u0644\\u062D\\u0627\\u0644\\u064A.",
    ["What scares me most is turning."] = "\\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0628\\u064A\\u062E\\u0648\\u0651\\u0641\\u0646\\u064A \\u0625\\u0646\\u064A \\u0623\\u062A\\u062D\\u0648\\u0651\\u0644.",
    ["What scares me most is fire."] = "\\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0628\\u064A\\u062E\\u0648\\u0651\\u0641\\u0646\\u064A \\u0627\\u0644\\u0646\\u0627\\u0631.",
    ["What scares me most is getting trapped in a tight space."] = "\\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0628\\u064A\\u062E\\u0648\\u0651\\u0641\\u0646\\u064A \\u0625\\u0646\\u064A \\u0623\\u0646\\u062D\\u0628\\u0633 \\u0628\\u0645\\u0643\\u0627\\u0646 \\u0636\\u064A\\u0651\\u0642.",
    ["What scares me most is letting people down."] = "\\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0628\\u064A\\u062E\\u0648\\u0651\\u0641\\u0646\\u064A \\u0625\\u0646\\u064A \\u0623\\u062E\\u0630\\u0644 \\u0627\\u0644\\u0646\\u0627\\u0633.",
    ["What scares me most is what waits in the dark."] = "\\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0628\\u064A\\u062E\\u0648\\u0651\\u0641\\u0646\\u064A \\u0627\\u0644\\u0644\\u064A \\u0628\\u064A\\u0633\\u062A\\u0646\\u0649 \\u0628\\u0627\\u0644\\u0639\\u062A\\u0645\\u0629.",
    ["I still check every exit. It helps me feel normal."] = "\\u0644\\u0633\\u0627 \\u0628\\u0634\\u064A\\u0651\\u0643 \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u0645\\u062E\\u0631\\u062C. \\u0628\\u064A\\u062D\\u0633\\u0651\\u0633\\u0646\\u064A \\u0625\\u0646\\u064A \\u0637\\u0628\\u064A\\u0639\\u064A\\u0629.",
    ["I still count our supplies twice. It helps me feel normal."] = "\\u0644\\u0633\\u0627 \\u0628\\u0639\\u062F\\u0651 \\u0645\\u0624\\u0646\\u0646\\u0627 \\u0645\\u0631\\u062A\\u064A\\u0646. \\u0628\\u064A\\u062D\\u0633\\u0651\\u0633\\u0646\\u064A \\u0625\\u0646\\u064A \\u0637\\u0628\\u064A\\u0639\\u064A\\u0629.",
    ["I still hum when I work. It helps me feel normal."] = "\\u0644\\u0633\\u0627 \\u0628\\u062F\\u0646\\u062F\\u0646 \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u0634\\u062A\\u063A\\u0644. \\u0628\\u064A\\u062D\\u0633\\u0651\\u0633\\u0646\\u064A \\u0625\\u0646\\u064A \\u0637\\u0628\\u064A\\u0639\\u064A\\u0629.",
    ["I still keep notes about each day. It helps me feel normal."] = "\\u0644\\u0633\\u0627 \\u0628\\u0643\\u062A\\u0628 \\u0645\\u0644\\u0627\\u062D\\u0638\\u0627\\u062A \\u0639\\u0646 \\u0643\\u0644 \\u064A\\u0648\\u0645. \\u0628\\u064A\\u062D\\u0633\\u0651\\u0633\\u0646\\u064A \\u0625\\u0646\\u064A \\u0637\\u0628\\u064A\\u0639\\u064A\\u0629.",
    ["I still make tea when I can. It helps me feel normal."] = "\\u0644\\u0633\\u0627 \\u0628\\u0639\\u0645\\u0644 \\u0634\\u0627\\u064A \\u0644\\u0645\\u0627 \\u0623\\u0642\\u062F\\u0631. \\u0628\\u064A\\u062D\\u0633\\u0651\\u0633\\u0646\\u064A \\u0625\\u0646\\u064A \\u0637\\u0628\\u064A\\u0639\\u064A\\u0629.",
    ["I still clean my tools before resting. It helps me feel normal."] = "\\u0644\\u0633\\u0627 \\u0628\\u0646\\u0638\\u0651\\u0641 \\u0623\\u062F\\u0648\\u0627\\u062A\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0623\\u0631\\u062A\\u0627\\u062D. \\u0628\\u064A\\u062D\\u0633\\u0651\\u0633\\u0646\\u064A \\u0625\\u0646\\u064A \\u0637\\u0628\\u064A\\u0639\\u064A\\u0629.",
    ["Keep clean bandages ready"] = "\\u062E\\u0644\\u0651\\u064A \\u0636\\u0645\\u0627\\u062F\\u0627\\u062A \\u0646\\u0636\\u064A\\u0641\\u0629 \\u062C\\u0627\\u0647\\u0632\\u0629",
    ["Find something worth reading"] = "\\u0644\\u0627\\u0642\\u064A \\u0634\\u064A \\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0627\\u0644\\u0642\\u0631\\u0627\\u0621\\u0629",
    ["Put our gear in order"] = "\\u0631\\u062A\\u0651\\u0628 \\u0639\\u062A\\u0627\\u062F\\u0646\\u0627",
    ["Improve this shelter"] = "\\u062A\\u062D\\u0633\\u064A\\u0646 \\u0647\\u0627\\u0644\\u0645\\u0644\\u062C\\u0623",
    ["Eat with company"] = "\\u0627\\u0644\\u0623\\u0643\\u0644 \\u0628\\u0635\\u062D\\u0628\\u0629",
    ["Recover the personal keepsake"] = "\\u0627\\u0633\\u062A\\u0631\\u062C\\u0627\\u0639 \\u0627\\u0644\\u062A\\u0630\\u0643\\u0627\\u0631 \\u0627\\u0644\\u0634\\u062E\\u0635\\u064A",
    ["I would feel better if we kept two clean bandages ready."] = "\\u0628\\u0628\\u0642\\u0649 \\u0623\\u062D\\u0633\\u0646 \\u0644\\u0648 \\u062E\\u0644\\u0651\\u064A\\u0646\\u0627 \\u0636\\u0645\\u0627\\u062F\\u062A\\u064A\\u0646 \\u0646\\u0636\\u064A\\u0641\\u062A\\u064A\\u0646 \\u062C\\u0627\\u0647\\u0632\\u062A\\u064A\\u0646.",
    ["I would like to find something worth reading when things are quiet."] = "\\u0628\\u062F\\u064A \\u0623\\u0644\\u0627\\u0642\\u064A \\u0634\\u064A \\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0627\\u0644\\u0642\\u0631\\u0627\\u0621\\u0629 \\u0644\\u0645\\u0627 \\u062A\\u0647\\u062F\\u0627 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0631.",
    ["I want to repair our worn gear before it fails us."] = "\\u0628\\u062F\\u064A \\u0623\\u0635\\u0644\\u0651\\u062D \\u0639\\u062A\\u0627\\u062F\\u0646\\u0627 \\u0627\\u0644\\u0645\\u0647\\u062A\\u0631\\u0626 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u062E\\u0630\\u0644\\u0646\\u0627.",
    ["I want to make this place a little harder for the dead to enter."] = "\\u0628\\u062F\\u064A \\u0623\\u062E\\u0644\\u0651\\u064A \\u0647\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0623\\u0635\\u0639\\u0628 \\u0634\\u0648\\u064A \\u0639\\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u064A\\u062F\\u062E\\u0644\\u0648\\u0647.",
    ["Would you keep me company while I eat? Just for a few minutes."] = "\\u0628\\u062A\\u0642\\u0639\\u062F \\u0645\\u0639\\u064A \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0622\\u0643\\u0644\\u061F \\u0628\\u0633 \\u0643\\u0645 \\u062F\\u0642\\u064A\\u0642\\u0629.",
    ["I am missing something personal. I would like it back."] = "\\u0646\\u0627\\u0642\\u0635\\u0646\\u064A \\u0634\\u064A \\u0634\\u062E\\u0635\\u064A. \\u0628\\u062F\\u064A \\u064A\\u0627\\u0647 \\u064A\\u0631\\u062C\\u0639.",
    ["Nothing specific. I need a little time to think."] = "\\u0648\\u0644\\u0627 \\u0634\\u064A \\u0645\\u062D\\u062F\\u062F. \\u0628\\u062F\\u064A \\u0634\\u0648\\u064A \\u0648\\u0642\\u062A \\u0644\\u0623\\u0641\\u0643\\u0651\\u0631.",
    ["I am not ready to talk about that yet."] = "\\u0644\\u0633\\u0627 \\u0645\\u0648 \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0623\\u062D\\u0643\\u064A \\u0639\\u0646 \\u0647\\u0627\\u0644\\u0634\\u064A.",
    ["Unknown personal goal"] = "\\u0647\\u062F\\u0641 \\u0634\\u062E\\u0635\\u064A \\u0645\\u062C\\u0647\\u0648\\u0644",
    ["You pushed me to take a fight I did not want."] = "\\u062F\\u0641\\u0639\\u062A\\u0646\\u064A \\u0644\\u0645\\u0639\\u0631\\u0643\\u0629 \\u0645\\u0627 \\u0643\\u0646\\u062A \\u0628\\u062F\\u0651\\u0627 \\u064A\\u0627\\u0647\\u0627.",
    ["You pushed me, and I got us through it."] = "\\u062F\\u0641\\u0639\\u062A\\u0646\\u064A\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0639\\u062F\\u0651\\u064A\\u062A\\u0646\\u0627 \\u0645\\u0646\\u0647\\u0627.",
    ["You pushed me into that fight, and I got hurt."] = "\\u062F\\u0641\\u0639\\u062A\\u0646\\u064A \\u0644\\u0647\\u062F\\u0627\\u0643 \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644\\u060C \\u0648\\u0627\\u0646\\u062C\\u0631\\u062D\\u062A.",
    ["You hit me. I warned you to watch your swing."] = "\\u0636\\u0631\\u0628\\u062A\\u0646\\u064A. \\u062D\\u0630\\u0651\\u0631\\u062A\\u0643 \\u062A\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0636\\u0631\\u0628\\u062A\\u0643.",
    ["You hit me again. I do not feel safe standing close to you."] = "\\u0636\\u0631\\u0628\\u062A\\u0646\\u064A \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629. \\u0645\\u0627 \\u0639\\u0645 \\u062D\\u0633 \\u0628\\u0623\\u0645\\u0627\\u0646 \\u0648\\u0623\\u0646\\u0627 \\u0648\\u0627\\u0642\\u0641\\u0629 \\u062C\\u0646\\u0628\\u0643.",
    ["You kept hitting me after I asked you to stop."] = "\\u0636\\u0644\\u0651\\u064A\\u062A \\u062A\\u0636\\u0631\\u0628\\u0646\\u064A \\u0628\\u0639\\u062F \\u0645\\u0627 \\u0637\\u0644\\u0628\\u062A \\u0645\\u0646\\u0643 \\u062A\\u0648\\u0642\\u0641.",
    ["You attacked me four times. I fought back."] = "\\u0647\\u062C\\u0645\\u062A \\u0639\\u0644\\u064A \\u0623\\u0631\\u0628\\u0639 \\u0645\\u0631\\u0627\\u062A. \\u0631\\u062F\\u064A\\u062A \\u0639\\u0644\\u064A\\u0643.",
    ["I stopped fighting when you were badly hurt, but I remember what happened."] = "\\u0648\\u0642\\u0651\\u0641\\u062A \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644 \\u0644\\u0645\\u0627 \\u0627\\u0646\\u062C\\u0631\\u062D\\u062A \\u0643\\u062A\\u064A\\u0631\\u060C \\u0628\\u0633 \\u0628\\u062A\\u0630\\u0643\\u0651\\u0631 \\u0634\\u0648 \\u0635\\u0627\\u0631.",
    ["I spared you, and you attacked me again. There will be no second ceasefire."] = "\\u0639\\u0641\\u064A\\u062A \\u0639\\u0646\\u0643\\u060C \\u0648\\u0647\\u062C\\u0645\\u062A \\u0639\\u0644\\u064A \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629. \\u0645\\u0627 \\u0631\\u062D \\u064A\\u0643\\u0648\\u0646 \\u0641\\u064A \\u0647\\u062F\\u0646\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629.",
    ["We managed something that mattered to me."] = "\\u0646\\u062C\\u062D\\u0646\\u0627 \\u0628\\u0634\\u064A \\u0643\\u0627\\u0646 \\u0645\\u0647\\u0645 \\u0639\\u0646\\u062F\\u064A.",
    ["We did it: %1."] = "\\u0639\\u0645\\u0644\\u0646\\u0627\\u0647\\u0627: %1.",
    ["I keep an old photo with me. It reminds me that there was a life before this."] = "\\u0628\\u062D\\u062A\\u0641\\u0638 \\u0628\\u0635\\u0648\\u0631\\u0629 \\u0642\\u062F\\u064A\\u0645\\u0629 \\u0645\\u0639\\u064A. \\u0628\\u062A\\u0630\\u0643\\u0651\\u0631\\u0646\\u064A \\u0625\\u0646\\u0648 \\u0643\\u0627\\u0646 \\u0641\\u064A \\u062D\\u064A\\u0627\\u0629 \\u0642\\u0628\\u0644 \\u0647\\u0627\\u062F.",
    ["This locket is one of the few personal things I have left."] = "\\u0647\\u0627\\u0644\\u0645\\u064A\\u062F\\u0627\\u0644\\u064A\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0642\\u0644\\u064A\\u0644 \\u0627\\u0644\\u0634\\u062E\\u0635\\u064A \\u0627\\u0644\\u0644\\u064A \\u0636\\u0644 \\u0645\\u0639\\u064A.",
    ["This watch belonged to someone I do not want to forget."] = "\\u0647\\u0627\\u0644\\u0633\\u0627\\u0639\\u0629 \\u0643\\u0627\\u0646\\u062A \\u0644\\u062D\\u062F\\u0627 \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0623\\u0646\\u0633\\u0627\\u0647.",
    ["I keep this journal so the days do not all disappear into each other."] = "\\u0628\\u062D\\u062A\\u0641\\u0638 \\u0628\\u0647\\u0627\\u0644\\u0645\\u0641\\u0643\\u0631\\u0629 \\u0644\\u062A\\u0636\\u0644 \\u0627\\u0644\\u0623\\u064A\\u0627\\u0645 \\u0645\\u0648 \\u0643\\u0644\\u0647\\u0627 \\u0630\\u0627\\u064A\\u0628\\u0629 \\u0628\\u0628\\u0639\\u0636\\u0647\\u0627.",
    ["I carry a small memento. It is personal, but I wanted you to know."] = "\\u0628\\u062D\\u0645\\u0644 \\u062A\\u0630\\u0643\\u0627\\u0631 \\u0635\\u063A\\u064A\\u0631. \\u0634\\u062E\\u0635\\u064A\\u060C \\u0628\\u0633 \\u062D\\u0628\\u064A\\u062A \\u062A\\u0639\\u0631\\u0641.",
    ["I am holding up. Point me where you need me."] = "\\u0639\\u0645 \\u0635\\u0645\\u062F. \\u062F\\u0644\\u0651\\u0646\\u064A \\u0648\\u064A\\u0646 \\u0628\\u062F\\u0643 \\u064A\\u0627\\u0646\\u064A.",
    ["I am holding up. I am still watching our exits."] = "\\u0639\\u0645 \\u0635\\u0645\\u062F. \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0631\\u0627\\u0642\\u0628 \\u0645\\u062E\\u0627\\u0631\\u062C\\u0646\\u0627.",
    ["I am all right. How are you holding up?"] = "\\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u0625\\u0646\\u062A \\u0643\\u064A\\u0641\\u0643\\u060C \\u0639\\u0645 \\u062A\\u0635\\u0645\\u062F\\u061F",
    ["I am holding up. Our supplies and gear are in order for now."] = "\\u0639\\u0645 \\u0635\\u0645\\u062F. \\u0645\\u0624\\u0646\\u0646\\u0627 \\u0648\\u0639\\u062A\\u0627\\u062F\\u0646\\u0627 \\u0645\\u0631\\u062A\\u0651\\u0628\\u064A\\u0646 \\u0647\\u0644\\u0623.",
    ["We can handle a fight, but only if it gets us somewhere."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062A\\u062D\\u0645\\u0651\\u0644 \\u0642\\u062A\\u0627\\u0644\\u060C \\u0628\\u0633 \\u0625\\u0630\\u0627 \\u0648\\u0635\\u0651\\u0644\\u0646\\u0627 \\u0644\\u0634\\u064A.",
    ["Slow and deliberate. I want a clear way back out."] = "\\u0628\\u0628\\u0637\\u0621 \\u0648\\u062A\\u0623\\u0646\\u0651\\u064A. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642 \\u0631\\u062C\\u0648\\u0639 \\u0648\\u0627\\u0636\\u062D.",
    ["We stay together and avoid fights that put either of us at needless risk."] = "\\u0645\\u0646\\u0636\\u0644 \\u0633\\u0648\\u0627 \\u0648\\u0645\\u0646\\u062A\\u062C\\u0646\\u0651\\u0628 \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0628\\u064A\\u0639\\u0631\\u0651\\u0636 \\u062D\\u062F\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0644\\u062E\\u0637\\u0631 \\u0628\\u0644\\u0627 \\u062F\\u0627\\u0639\\u064A.",
    ["We conserve ammunition, keep our tools ready, and choose useful fights."] = "\\u0645\\u0646\\u0648\\u0641\\u0651\\u0631 \\u0627\\u0644\\u0630\\u062E\\u064A\\u0631\\u0629\\u060C \\u0648\\u0645\\u0646\\u062E\\u0644\\u0651\\u064A \\u0623\\u062F\\u0648\\u0627\\u062A\\u0646\\u0627 \\u062C\\u0627\\u0647\\u0632\\u0629\\u060C \\u0648\\u0645\\u0646\\u062E\\u062A\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0631\\u0643 \\u0627\\u0644\\u0645\\u0641\\u064A\\u062F\\u0629.",
    ["I can try one run with you. Then I decide."] = "\\u0641\\u064A\\u0646\\u064A \\u062C\\u0631\\u0651\\u0628 \\u062C\\u0648\\u0644\\u0629 \\u0648\\u062D\\u062F\\u0629 \\u0645\\u0639\\u0643. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u0642\\u0631\\u0631.",
    ["One run. I am still responsible for getting myself home."] = "\\u062C\\u0648\\u0644\\u0629 \\u0648\\u062D\\u062F\\u0629. \\u0644\\u0633\\u0627 \\u0623\\u0646\\u0627 \\u0645\\u0633\\u0624\\u0648\\u0644 \\u0631\\u062C\\u0651\\u0639 \\u062D\\u0627\\u0644\\u064A \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A.",
    ["I need more time before I make that choice."] = "\\u0628\\u062F\\u064A \\u0648\\u0642\\u062A \\u0623\\u0643\\u062A\\u0631 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u062A\\u062E\\u0630 \\u0647\\u0627\\u0644\\u0642\\u0631\\u0627\\u0631.",
    ["I am going home. This is where I belong."] = "\\u0631\\u0627\\u064A\\u062D \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A. \\u0647\\u0648\\u0646 \\u0645\\u0643\\u0627\\u0646\\u064A.",
